#!/usr/bin/env bun
// Factual snapshot of the Epic Games and Bevy upstream surface, regenerated by
// .github/workflows/upstream-sync.yml. Every value comes from the GitHub GraphQL API;
// nothing is written by hand. Output: docs/epic/snapshot.json.
// Usage: GITHUB_TOKEN=... bun scripts/upstream-recon.ts [out]

import { rename } from "node:fs/promises";

const OWNERS = ["EpicGames", "bevyengine"];
// Community repositories tracked in docs/epic/RESOURCES.md.
const COMMUNITY = [
  "trumank/repak",
  "AstroTechies/unrealmodding",
  "FabianFG/CUE4Parse",
  "4sval/FModel",
  "UE4SS-RE/RE-UE4SS",
  "legendary-gl/legendary",
  "Heroic-Games-Launcher/HeroicGamesLauncher",
  "RareDevs/Rare",
  "3ddelano/epic-online-services-godot",
  "devphmd/eos",
  "verselang/book",
];

const token = process.env.GITHUB_TOKEN || process.env.GH_TOKEN;
if (!token) throw new Error("GITHUB_TOKEN or GH_TOKEN required");

const FIELDS = `nameWithOwner isArchived isPrivate pushedAt stargazerCount
  primaryLanguage { name } licenseInfo { spdxId }
  defaultBranchRef { name target { ... on Commit { oid committedDate messageHeadline } } }
  refs(refPrefix: "refs/heads/") { totalCount }
  latestRelease { tagName publishedAt }`;

async function gql(
  query: string,
  variables: Record<string, unknown> = {},
): Promise<any> {
  const res = await fetch("https://api.github.com/graphql", {
    method: "POST",
    headers: {
      authorization: `bearer ${token}`,
      "user-agent": "aphrody-upstream-recon",
    },
    body: JSON.stringify({ query, variables }),
  });
  const text = await res.text();
  let body: { data?: any; errors?: { message: string }[] };
  try {
    body = JSON.parse(text);
  } catch {
    throw new Error(`GraphQL ${res.status}: non-JSON response`);
  }
  if (!res.ok || !body.data || body.errors?.length)
    throw new Error(
      `GraphQL ${res.status}: ${body.errors?.map((e) => e.message).join("; ")}`,
    );
  return body.data;
}

async function orgRepos(login: string): Promise<any[]> {
  const out: any[] = [];
  let after: string | null = null;
  do {
    const d = await gql(
      `query($login:String!,$after:String){organization(login:$login){repositories(first:50,after:$after,orderBy:{field:PUSHED_AT,direction:DESC}){pageInfo{hasNextPage endCursor} nodes{${FIELDS}}}}}`,
      { login, after },
    );
    const page = d.organization.repositories;
    out.push(...page.nodes);
    after = page.pageInfo.hasNextPage ? page.pageInfo.endCursor : null;
  } while (after);
  return out;
}

async function namedRepos(names: string[]): Promise<any[]> {
  const parts = names.map((n, i) => {
    const [o, r] = n.split("/");
    return `r${i}: repository(owner: ${JSON.stringify(o)}, name: ${JSON.stringify(r)}) { ${FIELDS} }`;
  });
  const d = await gql(`{ ${parts.join("\n")} }`);
  return Object.values(d).filter(Boolean);
}

const row = (r: any) => ({
  repo: r.nameWithOwner,
  archived: r.isArchived,
  private: r.isPrivate,
  language: r.primaryLanguage?.name ?? null,
  license: r.licenseInfo?.spdxId ?? null,
  stars: r.stargazerCount,
  pushed: r.pushedAt,
  branches: r.refs?.totalCount ?? null,
  defaultBranch: r.defaultBranchRef?.name ?? null,
  head: r.defaultBranchRef?.target?.oid ?? null,
  headDate: r.defaultBranchRef?.target?.committedDate ?? null,
  headTitle: r.defaultBranchRef?.target?.messageHeadline ?? null,
  latestRelease: r.latestRelease
    ? { tag: r.latestRelease.tagName, date: r.latestRelease.publishedAt }
    : null,
});

// No timestamp: the file only changes when upstream state changes, so commits stay meaningful.
const byRepo = (a: { repo: string }, b: { repo: string }) =>
  a.repo.localeCompare(b.repo);
const snapshot: Record<string, unknown> = { source: "api.github.com/graphql" };
for (const o of OWNERS) snapshot[o] = (await orgRepos(o)).map(row).sort(byRepo);
snapshot.community = (await namedRepos(COMMUNITY)).map(row).sort(byRepo);

const out = process.argv[2] ?? "docs/epic/snapshot.json";
await Bun.write(`${out}.tmp`, JSON.stringify(snapshot, null, 2) + "\n");
await rename(`${out}.tmp`, out);
console.log(
  `${out}: ${OWNERS.map((o) => `${o}=${(snapshot[o] as unknown[]).length}`).join(" ")} community=${(snapshot.community as unknown[]).length}`,
);
